pub fn run(command: Command) -> Result<Value, ClewError> {
    match command {
        Command::Recover {
            root,
            captures,
            from_export,
            source_snapshot,
        } => match (from_export, source_snapshot) {
            (None, None) => super::capture_recovery::run(&root, &captures),
            (Some(export), Some(snapshot)) => {
                super::capture_export::run(&root, &export, &snapshot, &captures)
            }
            _ => Err(invalid(
                "--from-export and --source-snapshot must be supplied together",
            )),
        },
        Command::Pin {
            root,
            name,
            snapshot,
        } => pin(&root, &name, &snapshot),
        Command::Show { root, name } => show(&root, &name),
        Command::List { root } => list(&root),
        Command::Unpin { root, name } => unpin(&root, &name),
    }
}
